import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.CukOUUOK.js";const h=JSON.parse('{"title":"怀念一个从未存在过的时代：死亡螺旋的心理注脚","description":"一、一个令人不安的现象 在中国当下的公共舆论场中，有一种越来越显著的情绪：对毛泽东时代的怀念。 这种怀念跨越了阶层和年龄。它不仅存在于经历过那个时代的老一代人中，也广泛存在于从未经历过那个时代的年轻人…","frontmatter":{"title":"怀念一个从未存在过的时代：死亡螺旋的心理注脚","categories":"历史与文化","tags":["历史记忆","社会心理","意识形态"],"description":"一、一个令人不安的现象 在中国当下的公共舆论场中，有一种越来越显著的情绪：对毛泽东时代的怀念。 这种怀念跨越了阶层和年龄。它不仅存在于经历过那个时代的老一代人中，也广泛存在于从未经历过那个时代的年轻人…","date":"2026-09-05T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-09-05-nostalgia-for-a-time-that-never-was.md","filePath":"posts/2026-09-05-nostalgia-for-a-time-that-never-was.md","lastUpdated":1789992750000}'),a={name:"posts/2026-09-05-nostalgia-for-a-time-that-never-was.md"};function s(n,t,p,e,g,i){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="怀念一个从未存在过的时代-死亡螺旋的心理注脚" tabindex="-1">怀念一个从未存在过的时代：死亡螺旋的心理注脚 <a class="header-anchor" href="#怀念一个从未存在过的时代-死亡螺旋的心理注脚" aria-label="Permalink to &quot;怀念一个从未存在过的时代：死亡螺旋的心理注脚&quot;">​</a></h1><h3 id="一、一个令人不安的现象" tabindex="-1">一、一个令人不安的现象 <a class="header-anchor" href="#一、一个令人不安的现象" aria-label="Permalink to &quot;一、一个令人不安的现象&quot;">​</a></h3><p>在中国当下的公共舆论场中，有一种越来越显著的情绪：对毛泽东时代的怀念。</p><p>这种怀念跨越了阶层和年龄。它不仅存在于经历过那个时代的老一代人中，也广泛存在于从未经历过那个时代的年轻人中。它不仅存在于底层民众中，也存在于部分知识分子和中产阶级中。</p><p>这个现象令人不安，因为它提出了一个尖锐的问题：<strong>一个以系统性剥夺社会权力、摧毁公共讨论能力、制造大规模人道灾难为特征的时代，为什么会被越来越多的人怀念？</strong></p><p>要回答这个问题，我们必须同时做两件事：第一，认真对待这种怀念背后的真实诉求；第二，揭示这种怀念所暴露的更深层问题——<strong>它不仅是死亡螺旋的产物，更是死亡螺旋在心理层面自我完成的证据。</strong></p><h3 id="二、怀念的真实根基-改革承诺的落空" tabindex="-1">二、怀念的真实根基：改革承诺的落空 <a class="header-anchor" href="#二、怀念的真实根基-改革承诺的落空" aria-label="Permalink to &quot;二、怀念的真实根基：改革承诺的落空&quot;">​</a></h3><p>任何对&quot;毛时代怀念&quot;的轻蔑——说它是&quot;选择性记忆&quot;、是&quot;愚昧&quot;——都是智识上的偷懒。这种怀念有其真实的、不可忽视的社会根基。</p><p><strong>第一，平等承诺的落空。</strong> 改革开放承诺&quot;共同富裕&quot;，四十多年过去了，&quot;一部分人先富起来&quot;已经充分实现，但&quot;共同富裕&quot;仍然遥远。当人们看到少数人掌握了绝大多数社会财富，而大量普通劳动者在重压下喘息时，他们会回想起&quot;虽然穷，但大家都一样穷&quot;的画面。这种怀念的实质不是对贫穷的向往，而是<strong>对不平等的愤怒</strong>。</p><p><strong>第二，确定性承诺的落空。</strong> 市场经济带来了效率，也带来了不确定性。当一个人面临失业、大病、养老等风险时，他会本能地怀念那个&quot;虽然什么都没有，但至少不用担心&quot;的时代。这种怀念的实质不是对匮乏的向往，而是<strong>对不确定性的恐惧</strong>。</p><p><strong>第三，尊严承诺的落空。</strong> 当人们看到今天的官员腐败、资本傲慢、底层被践踏时，他们会回想起那个&quot;干部不敢欺负群众&quot;的时代。这种怀念的实质不是对专制的向往，而是<strong>对尊严缺失的抗议</strong>。</p><p><strong>第四，意义承诺的落空。</strong> 当人们感到生活空虚、被消费主义裹挟时，他们会回想起那个&quot;虽然苦，但有信仰&quot;的时代。这种怀念的实质不是对洗脑的向往，而是<strong>对意义真空的焦虑</strong>。</p><p>这四种落空构成了怀念的真实根基。否定这些根基，就是否定人们真实的生活体验。</p><p><strong>但承认怀念的真实根基，不等于承认怀念的对象是真实的。</strong> 这里存在一个深刻的认知错位：人们怀念的那个&quot;美好时代&quot;，在很大程度上是一个从未存在过的幻象。</p><h3 id="三、怀念的认知错位-一个从未存在过的时代" tabindex="-1">三、怀念的认知错位：一个从未存在过的时代 <a class="header-anchor" href="#三、怀念的认知错位-一个从未存在过的时代" aria-label="Permalink to &quot;三、怀念的认知错位：一个从未存在过的时代&quot;">​</a></h3><p><strong>&quot;人人平等&quot;的幻象。</strong> 毛时代的&quot;平等&quot;是极度匮乏中的平等。它掩盖了极其深刻的等级结构：城乡二元体制将中国人分为两个世界；政治等级制根据家庭出身划分&quot;红五类&quot;和&quot;黑五类&quot;；干部特权体系以政治权力为基础进行差异化分配；信息等级制使&quot;平等参与&quot;从根本上不可能。人们怀念的&quot;人人平等&quot;，是一个在话语层面存在但在现实中从未实现过的幻象。</p><p><strong>&quot;干部不敢欺负群众&quot;的幻象。</strong> 在毛时代的权力结构中，群众没有任何制度化的渠道来制约干部。你不能通过选举罢免、通过媒体揭露、通过司法起诉、通过工会谈判。你能做的只有等待上面发动运动——而这本身就是另一种形式的权力滥用。人们怀念的&quot;干部不敢欺负群众&quot;，是一个在个别运动期间短暂存在、但从未制度化的幻象。</p><p><strong>&quot;人心淳朴&quot;的幻象。</strong> 政治运动制造了极其普遍的人际背叛：夫妻互相揭发、子女划清界限、朋友反目成仇。这种&quot;不淳朴&quot;不是人性的堕落，而是制度制造的生存策略。人们怀念的&quot;人心淳朴&quot;，是一个选择性记忆过滤掉了恐惧和背叛之后的幻象。</p><p><strong>&quot;国家有尊严&quot;的幻象。</strong> 这种&quot;尊严&quot;主要是国家层面的，不是个人层面的。普通民众的生活水平在毛时代几乎没有提高。人们怀念的&quot;国家有尊严&quot;，是一个将国家荣耀等同于个人尊严的幻象。</p><h3 id="四、死亡螺旋的心理注脚-元认知能力的丧失" tabindex="-1">四、死亡螺旋的心理注脚：元认知能力的丧失 <a class="header-anchor" href="#四、死亡螺旋的心理注脚-元认知能力的丧失" aria-label="Permalink to &quot;四、死亡螺旋的心理注脚：元认知能力的丧失&quot;">​</a></h3><p>如果前两节回答了&quot;人们为什么怀念&quot;和&quot;怀念的对象在多大程度上是虚构的&quot;，那么这一节要追问一个更深的问题：<strong>为什么人们如此需要这种虚构？为什么他们不仅不质疑这种虚构，反而真诚地捍卫它？</strong></p><p>答案指向了死亡螺旋最深处、最隐秘的那个档位：<strong>元认知能力的彻底丧失。</strong></p><p>我们之前讨论过，死亡螺旋最恶毒的特征不是让人们&quot;不能思考&quot;，而是让人们<strong>不知道自己已经不能思考了</strong>。对毛时代的怀念，恰恰展现了这种元认知能力的彻底丧失。它在四个维度上表现得尤为清晰：</p><p><strong>第一，丧失了区分&quot;被动员&quot;和&quot;自发&quot;的能力。</strong></p><p>怀念者真诚地认为那个时代的&quot;群众运动&quot;是&quot;人民当家作主&quot;，是&quot;大民主&quot;。他们忘记了——或者说从未被告知——那些运动都是自上而下发起的，运动的对象、节奏、边界全部由上级预设。你只能&quot;响应&quot;，不能&quot;发起&quot;；只能&quot;拥护&quot;，不能&quot;反对&quot;。</p><p>他们把&quot;被动员的参与&quot;当成了&quot;真正的政治参与&quot;。这就像一个被关在笼子里的人，每天按时被放出来走两圈，然后真诚地认为自己是&quot;自由的&quot;。</p><p><strong>第二，丧失了区分&quot;平均&quot;和&quot;平等&quot;的能力。</strong></p><p>那个时代确实是&quot;平均&quot;的——大家都穷，都没有财产。但这不是&quot;平等&quot;。平等是有权利、有尊严、有选择权的平等。而那个时代的&quot;平均&quot;，是剥夺了所有人的选择权之后的人为拉平。</p><p>他们怀念&quot;大家都穿一样的衣服&quot;，却忘记了那是<strong>不允许穿不一样的衣服</strong>的结果。他们怀念&quot;没有贫富差距&quot;，却忘记了那是<strong>不允许任何人致富</strong>的结果。</p><p>这就像一个监狱里的囚犯怀念&quot;大家都穿一样的囚服，没有时尚焦虑&quot;——他没有意识到，这种&quot;没有焦虑&quot;的代价是&quot;没有自由&quot;。</p><p><strong>第三，丧失了区分&quot;秩序&quot;和&quot;压制&quot;的能力。</strong></p><p>那个时代确实&quot;稳定&quot;。但他们把这种&quot;稳定&quot;归因为&quot;社会和谐&quot;，而没有意识到那是<strong>不允许任何异议存在</strong>的结果。</p><p>他们忘记了那个时代的&quot;稳定&quot;是靠什么维持的：户口制度把人绑定在土地上，单位制度把人绑定在工作上，档案制度把人绑定在组织里，监控网络渗透到每一个街区。</p><p>这不是&quot;秩序&quot;，这是<strong>用铁链锁住的&quot;不动&quot;</strong>。但他们真诚地认为这是&quot;好的社会&quot;。</p><p><strong>第四，丧失了区分&quot;信仰&quot;和&quot;灌输&quot;的能力。</strong></p><p>那个时代的人确实&quot;有信仰&quot;。但这种&quot;信仰&quot;不是通过自由探索、理性思辨形成的，而是从出生开始就被系统性地灌输的。你读的书、听的广播、看的电影、上的学校、参加的组织，全部在重复同一个叙事。你没有接触过任何其他叙事，你甚至不知道世界上还有其他叙事。</p><p>这不是&quot;信仰&quot;，这是<strong>信息垄断制造的认知闭环</strong>。但他们真诚地认为这是&quot;精神富足&quot;。</p><p><strong>这就是死亡螺旋的心理注脚：被剥夺者不仅不觉得自己被剥夺了，还真诚地认为剥夺者是为自己好。</strong></p><p>这就像斯德哥尔摩综合征——人质不仅不恨绑匪，还开始同情绑匪，甚至帮绑匪说话。因为他们已经无法想象离开绑匪之后的生活。</p><h3 id="五、但这不全是他们的错" tabindex="-1">五、但这不全是他们的错 <a class="header-anchor" href="#五、但这不全是他们的错" aria-label="Permalink to &quot;五、但这不全是他们的错&quot;">​</a></h3><p>指责这些怀念者&quot;愚蠢&quot;或&quot;被洗脑&quot;是不诚实的。因为这种怀念的背后，有真实的结构性困境。</p><p><strong>第一，改革开放创造了财富，但没有创造意义。</strong> 市场经济让人们有了选择权，但也让人们承担了选择的全部责任和风险。你自由了，但你也孤独了。你有钱了，但你也焦虑了。当一个人面对这种存在主义的虚无时，他会本能地怀念那个&quot;不需要选择、不需要思考、不需要负责&quot;的时代。这不是因为他&quot;傻&quot;，而是因为人类心理本身就倾向于逃避自由——弗洛姆在《逃避自由》中精确地描述了这个机制。</p><p><strong>第二，当代社会的原子化加剧了这种怀念。</strong> 当代中国社会是高度原子化的。人们没有社区、没有工会、没有真正的社会组织。他们是孤立的个体，直接面对庞大的市场力量和国家机器。在这种孤立中，人们会本能地怀念那个&quot;有单位、有集体、有组织&quot;的时代——即使那个&quot;集体&quot;是虚假的，那个&quot;组织&quot;是管控性的。因为<strong>虚假的连接总比没有连接好</strong>，这是人类的心理本能。</p><p><strong>第三，公共讨论空间的缺失让这种怀念无法被纠正。</strong> 如果有一个健康的公共讨论空间，人们可以听到不同的声音，通过辩论和证据交换形成更复杂的判断。但今天的公共讨论空间是极度压缩的。人们听到的关于毛时代的信息，要么是官方叙事的&quot;功大于过&quot;，要么是民间流传的碎片化记忆。他们没有机会接触到系统的、基于证据的、多角度的历史分析。在这种信息环境中，&quot;怀念&quot;与其说是一个&quot;判断&quot;，不如说是一个&quot;情绪出口&quot;。</p><h3 id="六、最诚实的判断" tabindex="-1">六、最诚实的判断 <a class="header-anchor" href="#六、最诚实的判断" aria-label="Permalink to &quot;六、最诚实的判断&quot;">​</a></h3><p>这种怀念是死亡螺旋转到了最深处的证据——人们不仅丧失了能力，还丧失了对这种丧失的觉察。</p><p>但这种怀念本身，也是对这个死亡螺旋的无声控诉。</p><p>因为人们为什么会怀念那个时代？因为他们对这个时代不满意。他们不满意市场经济的残酷、不满意社会的不公、不满意意义的缺失、不满意原子化的孤独。这种不满意是真实的、正当的。只是他们把这种不满意投射到了一个错误的对象上——他们以为是&quot;自由&quot;让他们痛苦，其实是&quot;没有安全感的自由&quot;让他们痛苦；他们以为是&quot;选择&quot;让他们焦虑，其实是&quot;没有支持的选择&quot;让他们焦虑。</p><p>这就像一个饿极了的人，看到了一张画着面包的图片，就以为那是真的面包。你不能指责他&quot;傻&quot;——他只是在用他唯一知道的方式，表达他真实的饥饿。</p><p><strong>我们的任务，也许不是指责这种怀念，而是理解这种怀念背后的真实需求，然后告诉人们：你们想要的东西——安全感、意义感、归属感、尊严——是可以和自由、多样性、选择权共存的。你们不需要在&quot;毛时代&quot;和&quot;新自由主义&quot;之间二选一。还有第三条路。</strong></p><p>而知道&quot;还有第三条路&quot;的前提，是知道&quot;本来可以是别的样子&quot;——不是国家吞并社会，而是社会收回国家；不是少数人代表多数人，而是多数人自己行使权力；不是用铁链锁住的&quot;稳定&quot;，而是在规则内处理冲突的&quot;秩序&quot;。</p><p>这也许就是我们写这三篇文章的全部意义：<strong>不是为了批判过去，而是为了打开未来的可能性。</strong></p><p>让那些怀念者知道：你们怀念的那些东西——安全感、意义感、归属感——不是必须用自由来交换的。你们可以都要。</p><p>而想要都要，首先得知道&quot;本来可以是别的样子&quot;。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2079499304209756666" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',56)])])}const d=o(a,[["render",s]]);export{h as __pageData,d as default};
